@IsTest private class OwnedViewQueryTest {
 @IsTest static void metadataRows() {
  List<ListView> views=[SELECT Id,Name,DeveloperName,SobjectType,NamespacePrefix,IsSoqlCompatible FROM ListView WHERE SobjectType='OwnedViewRecord__c' AND DeveloperName IN ('OwnedViewAll','OwnedViewEnabled') WITH SYSTEM_MODE ORDER BY DeveloperName];
  System.assertEquals(2,views.size());
  for(ListView view:views){System.assertEquals('OwnedViewRecord__c',view.SobjectType);System.assertEquals(null,view.NamespacePrefix);System.assertEquals(true,view.IsSoqlCompatible);System.assertNotEquals(null,view.Id);System.assertNotEquals(null,view.Name);}
  ListView chosen=[SELECT Id,Name,DeveloperName,IsSoqlCompatible FROM ListView WHERE SobjectType='OwnedViewRecord__c' AND DeveloperName='OwnedViewAll' AND IsSoqlCompatible=true WITH SYSTEM_MODE LIMIT 1];System.assertEquals('Owned All',chosen.Name);
 }
}

